#!/bin/sh
# Installs helo from the latest GitHub release of https://github.com/helo-email/helo-cli:
#
#   curl -fsSL https://raw.githubusercontent.com/helo-email/helo-cli/main/install.sh | sh
#
# It downloads with curl rather than a browser, so macOS doesn't quarantine the
# binary and Gatekeeper runs it without a warning.
#
#   HELO_INSTALL_DIR      where to install (default: ~/.local/bin)
#   HELO_INSTALL_VERSION  a release to install instead, e.g. 0.3.1
#   HELO_INSTALL_RELEASES_URL  a mirror of https://github.com/helo-email/helo-cli/releases
#
# Generated by helo-sdk-generator.
set -eu

name=helo
releases="${HELO_INSTALL_RELEASES_URL:-https://github.com/helo-email/helo-cli/releases}"
install_dir="${HELO_INSTALL_DIR:-$HOME/.local/bin}"
version="${HELO_INSTALL_VERSION:-}"

fail() {
  echo "error: $*" >&2
  exit 1
}

case "$(uname -s)" in
  Darwin) os=darwin ;;
  Linux) os=linux ;;
  *) fail "unsupported OS $(uname -s): download $name from $releases" ;;
esac

case "$(uname -m)" in
  x86_64 | amd64) arch=amd64 ;;
  arm64 | aarch64) arch=arm64 ;;
  *) fail "unsupported architecture $(uname -m): download $name from $releases" ;;
esac
# A shell running under Rosetta reports x86_64 on Apple silicon.
if [ "$os" = darwin ] && [ "$arch" = amd64 ] && [ "$(sysctl -n sysctl.proc_translated 2>/dev/null)" = 1 ]; then
  arch=arm64
fi

if [ -n "$version" ]; then
  download="$releases/download/v${version#v}"
else
  download="$releases/latest/download"
fi
archive="${name}_${os}_${arch}.tar.gz"

command -v curl >/dev/null 2>&1 || fail "curl is required"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

echo "Downloading $download/$archive"
curl -fsSL -o "$tmp/$archive" "$download/$archive" || fail "couldn't download $download/$archive"
curl -fsSL -o "$tmp/checksums.txt" "$download/checksums.txt" || fail "couldn't download $download/checksums.txt"

expected=$(awk -v archive="$archive" '$2 == archive { print $1 }' "$tmp/checksums.txt")
[ -n "$expected" ] || fail "checksums.txt has no entry for $archive"
if command -v sha256sum >/dev/null 2>&1; then
  actual=$(sha256sum "$tmp/$archive" | awk '{ print $1 }')
else
  actual=$(shasum -a 256 "$tmp/$archive" | awk '{ print $1 }')
fi
[ "$actual" = "$expected" ] || fail "$archive doesn't match its checksum"

tar -xzf "$tmp/$archive" -C "$tmp" "$name"
mkdir -p "$install_dir"
install -m 0755 "$tmp/$name" "$install_dir/$name"
echo "Installed $("$install_dir/$name" --version) to $install_dir/$name"

case ":$PATH:" in
  *":$install_dir:"*) ;;
  *) echo "$install_dir isn't on your PATH; add it to run $name by name." ;;
esac
